class Solution {
public:
    int shortestPathWithHops(int n, vector<vector<int>>& edges, int s, int d, int k) {
        vector<vector<pair<int,int>>> g(n);
        for (auto& e : edges) {
            g[e[0]].push_back({e[1], e[2]});
            g[e[1]].push_back({e[0], e[2]});
        }
        const long long INF = LLONG_MAX / 4;
        vector<vector<long long>> dist(n, vector<long long>(k + 1, INF));
        priority_queue<tuple<long long,int,int>, vector<tuple<long long,int,int>>,
                       greater<tuple<long long,int,int>>> pq;
        dist[s][k] = 0;
        pq.emplace(0, s, k);
        while (!pq.empty()) {
            long long cost; int u, remaining;
            tie(cost, u, remaining) = pq.top(); pq.pop();
            if (cost != dist[u][remaining]) continue;
            if (u == d) return (int)cost;
            for (auto e : g[u]) {
                int v = e.first, weight = e.second;
                if (cost + weight < dist[v][remaining]) {
                    dist[v][remaining] = cost + weight;
                    pq.emplace(cost + weight, v, remaining);
                }
                if (remaining && cost < dist[v][remaining - 1]) {
                    dist[v][remaining - 1] = cost;
                    pq.emplace(cost, v, remaining - 1);
                }
            }
        }
        return -1;
    }
};
